import assert from 'node:assert/strict';
import {readFileSync, writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {machineCid} from './actql-spec-family.mjs';
import {resolvePointer} from './check-canonical-json.mjs';

// The interpretation contract is not the concrete Check Environment envelope.
const contract = JSON.parse(readFileSync('spec/contracts/actql-check-environment.json', 'utf8'));
const pushdown = contract.pushdown_contract_bodies;
const operations = pushdown.schema.oneOf[1].properties.operations.items.enum;
const text = [
  '// Generated by scripts/catalog-body-dependencies.mjs; do not edit.',
  '', '///|', 'fn catalog_body_grammar_cid() -> String {',
  `  ${JSON.stringify(machineCid(contract))}`, '}', '',
  ...Object.entries(pushdown.semantic_dependencies).flatMap(([name, pin])=>[
    '///|', `fn pushdown_${name}_cid() -> String {`, `  ${JSON.stringify(pin.cid)}`, '}', '',
  ]),
  '///|', 'fn pushdown_operation_limit() -> Int {', `  ${operations.length}`, '}', '',
  '///|', 'fn pushdown_operation_name(name : String) -> Bool {', '  match name {',
  `    ${operations.map(name=>JSON.stringify(name)).join(' | ')} => true`,
  '    _ => false', '  }', '}', '',
].join('\n');
const path = 'src/check_environment/body_grammar.generated.mbt';
if (process.argv.includes('--write')) writeFileSync(path, text);
assert.equal(readFileSync(path, 'utf8'), text);
console.log('Catalog body interpretation contract pin verified.');

// Only declared reference positions are edges. Schema field names, source-file
// checksums, and CID-shaped application data do not participate in this graph.
const read = path => JSON.parse(readFileSync(path, 'utf8'));
const base = read('spec/dependencies/actql-text-time-base.json');
const inherited = read('spec/dependencies/actql-text-time-base-dependencies.json');
const unicode = read('spec/dependencies/actql-text-time-unicode-data.json');
const bodies = {
  Base: base,
  SourceSchema: base.source_schema,
  EnvelopeSchema: base.evaluation_envelope_schema,
  BarrierSchema: base.barrier_schema,
  RegexGrammar: inherited.regex_grammar,
  RegexAst: inherited.regex_ast_schema,
  ReplacementAst: inherited.regex_replacement_ast_schema,
  TimestampGrammar: inherited.timestamp_pattern_grammar,
  TimestampAst: inherited.timestamp_pattern_ast_schema,
  UnicodeSemantics: inherited.unicode_semantics,
  UnicodeData: unicode,
};
const edges = {
  Base: [
    ['/source_schema_cid', 'SourceSchema'],
    ['/evaluation_envelope_schema_cid', 'EnvelopeSchema'],
    ['/barrier_schema_cid', 'BarrierSchema'],
    ['/data_contract_cids/regex_grammar_cid', 'RegexGrammar'],
    ['/data_contract_cids/timestamp_pattern_grammar_cid', 'TimestampGrammar'],
    ['/data_contract_cids/unicode_data_cid', 'UnicodeSemantics'],
    ['/bound_derivation/nfkc/unicode_data_cid', 'UnicodeData'],
    ['/bound_derivation/case_fold/unicode_data_cid', 'UnicodeData'],
  ],
  SourceSchema: [], EnvelopeSchema: [], BarrierSchema: [],
  RegexGrammar: [['/ast_schema_cid', 'RegexAst'], ['/replacement_ast_schema_cid', 'ReplacementAst']],
  RegexAst: [], ReplacementAst: [],
  TimestampGrammar: [['/ast_schema_cid', 'TimestampAst']], TimestampAst: [],
  UnicodeSemantics: [['/data_cid', 'UnicodeData']], UnicodeData: [],
};
assert.deepEqual(Object.keys(edges), Object.keys(bodies));
const pins = Object.fromEntries(Object.entries(bodies).map(([name, body]) => [name, machineCid(body)]));
assert.equal(pins.Base, read('spec/contracts/actql-expressions.json').inherited_text_time_profile_cid);
assert.equal(new Set(Object.values(pins)).size, Object.keys(bodies).length);
for (const [name, references] of Object.entries(edges)) {
  for (const [pointer, target] of references) {
    assert.equal(pointer.slice(1).split('/').reduce((value, part) => value[part], bodies[name]), pins[target]);
  }
}
const lines = [
  '// Generated by scripts/catalog-body-dependencies.mjs; do not edit.',
  '', '///|', '/// Interpret the inherited edge only, not the whole expression contract.',
  'pub fn inherited_text_time_for_expression(cid : String) -> InheritedTextTimeContract? {',
  `  if cid == ${JSON.stringify(machineCid(read('spec/contracts/actql-expressions.json')))} {`,
  '    Some(Base)', '  } else {', '    None', '  }', '}',
  '', '///|', 'pub(all) enum InheritedTextTimeContract {',
  ...Object.keys(bodies).map(name => `  ${name}`),
  '} derive(Eq, Debug)', '', '///|', 'pub struct InheritedTextTimeDependency {',
  '  pointer : String', '  target : InheritedTextTimeContract', '}', '',
  '///|', '/// Resolve only this inherited contract family. None means unknown, not a leaf.',
  'pub fn inherited_text_time_contract(cid : String) -> InheritedTextTimeContract? {',
  '  match cid {', ...Object.entries(pins).map(([name, cid]) => `    ${JSON.stringify(cid)} => Some(${name})`),
  '    _ => None', '  }', '}', '',
  '///|', 'pub fn inherited_text_time_cid(v : InheritedTextTimeContract) -> String {',
  '  match v {', ...Object.entries(pins).map(([name, cid]) => `    ${name} => ${JSON.stringify(cid)}`),
  '  }', '}', '',
  '///|', 'pub fn inherited_text_time_dependency_count(v : InheritedTextTimeContract) -> Int {',
  '  match v {', ...Object.entries(edges).map(([name, refs]) => `    ${name} => ${refs.length}`),
  '  }', '}', '',
  '///|', '/// Preserve repeated reference sites even when their target CID is equal.',
  'pub fn inherited_text_time_dependency_at(', '  v : InheritedTextTimeContract,', '  index : Int,',
  ') -> InheritedTextTimeDependency? {', '  match v {',
  ...Object.entries(edges).flatMap(([name, refs]) => refs.length ? [
    `    ${name} => match index {`,
    ...refs.map(([pointer, target], i) => `      ${i} => Some({ pointer: ${JSON.stringify(pointer)}, target: ${target} })`),
    '      _ => None', '    }',
  ] : [`    ${name} => None`]),
  '  }', '}', '',
];
const inheritedPath = 'src/check_environment/inherited_text_time.generated.mbt';
const inheritedText = lines.join('\n');
if (process.argv.includes('--write')) writeFileSync(inheritedPath, inheritedText);
assert.equal(readFileSync(inheritedPath, 'utf8'), inheritedText);
console.log('Inherited text/time dependency roles and body pins verified.');

const expression = read('spec/contracts/actql-expressions.json');
const regex = read(expression.regex_ast_contract.path);
assert.equal(expression.regex_ast_contract.pointer, '');
assert.equal(regex.schema.pointer, '');
const expressionBodies = {
  root: expression,
  regex_contract: regex,
  regex_schema: read(regex.schema.path),
  consumer_capacity: read('spec/contracts/actql-consumer-capacity.json'),
};
const expressionPins = Object.fromEntries(Object.entries(expressionBodies).map(([name, body]) => [name, machineCid(body)]));
assert.equal(expressionPins.regex_contract, expression.regex_ast_contract.cid);
assert.equal(expressionPins.regex_schema, regex.schema.cid);
assert.equal(expressionPins.consumer_capacity, expression.laws.consumer_capacity_contract_cid);
// The EBNF is a byte-hashed resource, not a canonical-JSON contract body.
assert.equal(createHash('sha256').update(readFileSync(expression.grammar)).digest('hex'), expression.grammar_sha256);
const expressionText = [
  '// Generated by scripts/catalog-body-dependencies.mjs; do not edit.', '',
  ...Object.entries(expressionPins).flatMap(([name, cid]) => [
    '///|', `fn expression_dependency_${name}_cid() -> String {`, `  ${JSON.stringify(cid)}`, '}', '',
  ]),
].join('\n');
const expressionPath = 'src/check_environment/expression_dependencies.generated.mbt';
if (process.argv.includes('--write')) writeFileSync(expressionPath, expressionText);
assert.equal(readFileSync(expressionPath, 'utf8'), expressionText);
console.log('Current expression dependency pins and grammar bytes verified.');

const aoa = read('spec/contracts/actql-aoa.json');
const adopted = [
  ['RelaScalar', 'aoa-rela-scalar-laws', 'rela_scalar_law_manifest_cid'],
  ['RelaPrimitive', 'aoa-rela-primitive-laws', 'rela_primitive_law_manifest_cid'],
  ['SgaStructural', 'aoa-sga-structural-laws', 'sga_structural_law_manifest_cid'],
  ['SgaIdentity', 'aoa-sga-identity-laws', 'sga_identity_law_manifest_cid'],
  ['VecaNumeric', 'aoa-veca-numeric-laws', 'veca_numeric_law_manifest_cid'],
];
for (const [, file, pin] of adopted) {
  assert.equal(machineCid(read(`spec/dependencies/${file}.json`)), aoa[pin]);
}
const adoptedText = [
  '// Generated by scripts/catalog-body-dependencies.mjs; do not edit.', '',
  '///|', 'pub fn adopted_operation_law_cid(law : AdoptedOperationLaw) -> String {',
  '  match law {',
  ...adopted.flatMap(([name, , pin]) => [`    ${name} =>`, `      ${JSON.stringify(aoa[pin])}`]),
  '  }', '}', '',
].join('\n');
const adoptedPath = 'src/pipeline_typing/adopted_laws.generated.mbt';
if (process.argv.includes('--write')) writeFileSync(adoptedPath, adoptedText);
assert.equal(readFileSync(adoptedPath, 'utf8'), adoptedText);
console.log('Adopted operation law body pins verified.');

const grammarReferences = [
  ['ValueGrammarBody', '/value_contract_bodies/schema/cid', contract.value_contract_bodies.schema],
  ['GraphLawBody', '/carrier_contract_bodies/schema/oneOf/1/properties/identity_law_cid/const',
    {path: 'spec/dependencies/aoa-sga-identity-laws.json', pointer: '', cid: aoa.sga_identity_law_manifest_cid}],
  ['GraphLawBody', '/carrier_contract_bodies/schema/oneOf/1/properties/value_law_cid/const',
    {path: 'spec/dependencies/aoa-sga-identity-laws.json', pointer: '', cid: aoa.sga_identity_law_manifest_cid}],
  ['RelationLawBody', '/pushdown_contract_bodies/semantic_dependencies/relation_laws/cid', pushdown.semantic_dependencies.relation_laws],
  ['ExpressionGrammar(ExpressionRoot)', '/pushdown_contract_bodies/semantic_dependencies/expression_contract/cid', pushdown.semantic_dependencies.expression_contract],
  ['TextPolicyGrammarBody', '/policy_components/text_time_evaluation/schema/cid', contract.policy_components.text_time_evaluation.schema],
  ['CapacityGrammarBody', '/policy_components/capacity/contract/cid', contract.policy_components.capacity.contract],
];
for (const [, pointer, ref] of grammarReferences) {
  assert.equal(resolvePointer(contract, pointer), ref.cid);
  assert.equal(machineCid(resolvePointer(read(ref.path ?? ref.file), ref.pointer)), ref.cid);
}
const grammarText = [
  '// Generated by scripts/catalog-body-dependencies.mjs; do not edit.', '',
  '///|', 'pub fn catalog_grammar_cid(body : CatalogGrammar) -> String {',
  '  match body {',
  `    EnvironmentBody => ${JSON.stringify(machineCid(contract))}`,
  ...grammarReferences.filter(([kind], i, refs) => !kind.startsWith('ExpressionGrammar') && refs.findIndex(([k]) => k === kind) === i)
    .flatMap(([kind, , ref]) => [`    ${kind} =>`, `      ${JSON.stringify(ref.cid)}`]),
  '    ExpressionGrammar(body) => expression_contract_body_cid(body)', '  }', '}', '',
  '///|', 'fn environment_grammar_edge(index : Int) -> CatalogGrammarDependency? {',
  '  match index {', ...grammarReferences.map(([target, pointer], index) =>
    `    ${index} => Some({ pointer: ${JSON.stringify(pointer)}, target: ${target} })`),
  '    _ => None', '  }', '}', '',
  '///|', 'fn environment_grammar_edge_count() -> Int {', `  ${grammarReferences.length}`, '}', '',
].join('\n');
const grammarPath = 'src/check_environment/catalog_grammar.generated.mbt';
if (process.argv.includes('--write')) writeFileSync(grammarPath, grammarText);
assert.equal(readFileSync(grammarPath, 'utf8'), grammarText);
console.log('Catalog interpretation dependency bodies and explicit roles verified.');

// The Program resource owns its recursive $defs. A parameter subschema alone
// would lose that scope; the enclosing Plan artifact is not the source grammar.
const protocol = read('spec/contracts/actql-protocol-schemas.json');
const program = protocol.artifact_schemas.executable_plan.properties.execution_material.properties.program;
assert.deepEqual(program, protocol.artifact_schemas.plan_document.properties.plan.properties.execution_material.properties.program);
for (const name of ['executable_plan', 'plan_document']) {
  assert.equal(machineCid(protocol.artifact_schemas[name]), protocol.artifact_schema_cids[name]);
}
function checkProgramRefs(value, root = false) {
  if (!value || typeof value !== 'object') return;
  if (!root) assert.ok(!Object.hasOwn(value, '$id'), 'nested schema resource needs explicit scope handling');
  if (typeof value.$ref === 'string') {
    assert.ok(value.$ref.startsWith('#/'), 'external Program schema dependency needs explicit handling');
    assert.ok(resolvePointer(program, value.$ref.slice(1)));
  }
  for (const child of Object.values(value)) checkProgramRefs(child);
}
checkProgramRefs(program, true);
const programText = [
  '// Generated by scripts/catalog-body-dependencies.mjs; do not edit.', '', '///|',
  'pub fn program_source_grammar_cid() -> String {',
  `  ${JSON.stringify(machineCid(program))}`, '}', '',
].join('\n');
const programPath = 'src/check_environment/program_grammar.generated.mbt';
if (process.argv.includes('--write')) writeFileSync(programPath, programText);
assert.equal(readFileSync(programPath, 'utf8'), programText);
console.log('Program source grammar scope and containing artifact pins verified.');

const stagePath = 'spec/contracts/actql-stage-contracts.json';
const stageContracts = read(stagePath);
const imports = read('spec/spec-family.json').documents.flatMap(d => d.machine_contracts ?? []);
const stageSemantics = [['SourceRules', '/source'], ['StageLaws', '/laws'],
  ['ResultImportInterface', '/schemas/result_import_interface']];
const semanticLines = [];
for (const [name, pointer] of stageSemantics) {
  const body = resolvePointer(stageContracts, pointer);
  const refs = imports.filter(r => r.path === stagePath && r.pointer === pointer);
  assert.ok(refs.length > 0, `unregistered stage semantics: ${pointer}`);
  for (const ref of refs) assert.equal(ref.cid, machineCid(body));
  semanticLines.push(`    ${name} =>`, `      ${JSON.stringify(refs[0].cid)}`);
}
const semanticText = [
  '// Generated by scripts/catalog-body-dependencies.mjs; do not edit.', '',
  '///|', 'pub(all) enum StageSemanticContract {',
  ...stageSemantics.map(([name]) => `  ${name}`), '} derive(Eq, Debug)', '',
  '///|', 'pub fn stage_semantic_contract_cid(body : StageSemanticContract) -> String {',
  '  match body {', ...semanticLines, '  }', '}', '',
].join('\n');
const semanticPath = 'src/check_environment/stage_semantics.generated.mbt';
if (process.argv.includes('--write')) writeFileSync(semanticPath, semanticText);
assert.equal(readFileSync(semanticPath, 'utf8'), semanticText);
console.log('Registered Stage source and semantic law pins verified.');
